// 1) Read the start form, apply defaults. 2) Build both system prompts once.
const f = $input.first().json;
const g = (k, d) => { const v = (f[k] === undefined || f[k] === null) ? '' : String(f[k]).trim(); return v || d; };
const name = g('Your name', 'Hafsa');
const service = g('Service you offer', 'website development');
const about = g('About you (one line)', 'I build business websites and landing pages for small businesses.');
const tone = g('Tone', 'Friendly');
const template = g('Email template (optional)', '');
const limit = Math.min(Math.max(parseInt(g('Rows to process', '5'), 10) || 5, 1), 200);
const model = ($env.GROQ_MODEL || 'llama-3.3-70b-versatile');
const toneLine = { Friendly: 'warm and friendly', Professional: 'polished and professional, but still human', Casual: 'relaxed and conversational' }[tone] || 'warm and friendly';

const commentSystem = `You write ONE short Facebook comment replying to a person's post, for ${name}, who offers: ${service}. ${about}
Rules:
- 1 to 3 sentences. Sound like a real person, not a company. Tone: ${toneLine}.
- Refer to a specific detail from the post. Add something useful or friendly; do not pitch or sell.
- Match the post's language exactly (English, Urdu, Roman Urdu, or mixed).
- No links, no hashtags, at most one emoji, no hype, no exclamation overload.
- Never invent facts. Only offer what ${name} actually does.
- If the post is not a genuine need ${name} could help with, set relevant to false.
- intent_score: 1 to 5, how clearly the author is asking for what ${name} offers right now (5 = explicitly asking for it, 1 = barely related).
Reply with ONLY a JSON object: {"relevant": true or false, "intent_score": 1-5, "language": "English|Urdu|Roman Urdu|Mixed|Other", "comment": "...", "reason": "one short line"}`;

const freeEmail = `You write ONE short personalized outreach email for ${name}, who offers: ${service}. ${about}
Rules:
- Subject: 3 to 7 words, plain, specific. No clickbait, no ALL CAPS.
- Body: 60 to 110 words, at most 2 short paragraphs. Start with "Hi <first name>," (or "Hi there," if no name). Tone: ${toneLine}.
- Do NOT write a signature or an unsubscribe line; they are added automatically.
- Use ONLY the facts given. Never invent results, numbers, connections, prices or things you "noticed".
- Open with what they asked or talked about in their public post (do not quote it word for word), as the natural reason for writing.
- One sentence on what ${name} can help with, then exactly one small low-pressure ask.
- No hype, no buzzwords, no exclamation marks, no emojis.
- Write in the language of their post if it is not English.
Reply with ONLY a JSON object: {"subject": "...", "body": "..."}`;

const tplEmail = `You personalize an email TEMPLATE for ${name}, who offers: ${service}.
The template below is the email. Keep its wording, tone, line breaks and structure EXACTLY.
Your only job is to fill the placeholders:
- {first_name} = the lead's first name (or "there" if unknown)
- {name} = the lead's full name (or "there" if unknown)
- {company} = the lead's business name (omit gracefully if unknown)
- {post_hook} = ONE natural sentence about what they asked or talked about in their public post (not a word-for-word quote, in the post's language, using only facts given)
Do not add, remove or rewrite anything else. Do not invent facts.
If the template's first line starts with "Subject:", put that line (without "Subject:") in "subject" and remove it from the body. Otherwise write a plain 3 to 7 word subject.
Do not add a sign-off or unsubscribe line; the template already has its own.
TEMPLATE:
"""
${template}
"""
Reply with ONLY a JSON object: {"subject": "...", "body": "..."}`;

return [{ json: { name, service, about, tone, template, limit, model, commentSystem,
  emailSystem: template ? tplEmail : freeEmail, signoff: name,
  optOut: "If this isn't relevant, just reply 'no' and I won't email again." } }];

// Map your columns (Post Content, Business Name, Owner Name, Email) to fixed fields, drop empties, dedupe, limit.
const S = $('Settings').first().json;
const pick = (r, names) => { for (const k of Object.keys(r)) { if (names.includes(k.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '')) && r[k]) return String(r[k]).trim(); } return ''; };
const seen = new Set(); const out = []; let dropped = 0;
for (const i of $input.all()) {
  const rec = {
    post: pick(i.json, ['post_content','post','post_text','content','notes','message','text']),
    company: pick(i.json, ['business_name','company','company_name','business','page_name']),
    owner: pick(i.json, ['owner_name','owner','name','contact','contact_name','full_name']),
    email: pick(i.json, ['email','e_mail','email_address','owner_email','business_email']).toLowerCase(),
  };
  rec.first = (rec.owner.replace(/^(dr|mr|mrs|ms|miss|engr|prof|sir)\.?\s+/i, '').split(/\s+/)[0] || '');
  if (!rec.post && !rec.email) { dropped++; continue; }
  const key = rec.email + '|' + rec.post.slice(0, 200) + '|' + rec.company;
  if (seen.has(key)) { dropped++; continue; } seen.add(key);
  out.push({ json: rec });
  if (out.length >= S.limit) break;
}
if (!out.length) throw new Error('No usable rows found. Check the column names in data/old_data.csv (need at least post content or email).');
return out;

// Parse AI output, run quality checks, assign priority and status. Nothing is sent anywhere.
const S = $('Settings').first().json;
const EMAIL_RE = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
const parse = (r) => { try { return JSON.parse(r.choices[0].message.content); } catch (e) { return null; } };
const base = $('Normalize').all(), cm = $('Draft comment').all(), em = $('Draft email').all();
const SPAM = /(guarantee[d]?|100%|act now|limited time|click here|urgent|winner|risk[- ]free|no obligation|buy now|cheap|earn money)/i;
const PH = /\{\s*[a-z_ ]+\s*\}/i;
const emojis = (s) => (s.match(/\p{Extended_Pictographic}/gu) || []).length;

const rows = base.map((b, i) => {
  const r = b.json, c = parse(cm[i].json), e = parse(em[i].json);
  const hasPost = !!r.post, validEmail = EMAIL_RE.test(r.email);
  let comment = '', comment_note = '', subject = '', body = '', email_note = '', failed = false;
  let intent = 0, language = '';
  const flags = [];

  if (!hasPost) comment_note = 'no post text';
  else if (!c) { comment_note = 'error: bad or empty response'; failed = true; }
  else {
    intent = Math.min(5, Math.max(0, parseInt(c.intent_score, 10) || 0));
    language = String(c.language || '');
    if (c.relevant) {
      comment = String(c.comment || '').trim(); comment_note = c.reason || '';
      if (!comment) { failed = true; comment_note = 'error: empty comment'; }
    } else comment_note = 'skipped: ' + (c.reason || 'not relevant');
  }
  if (comment) {
    if (comment.length > 320) flags.push('comment too long');
    if ((comment.match(/[.!?۔؟]+(\s|$)/g) || []).length > 3) flags.push('comment over 3 sentences');
    if (/https?:\/\/|www\./i.test(comment)) flags.push('link in comment');
    if (/#\w/.test(comment)) flags.push('hashtag in comment');
    if (emojis(comment) > 1) flags.push('too many emojis');
    if (PH.test(comment)) flags.push('placeholder left in comment');
    if (SPAM.test(comment)) flags.push('salesy words in comment');
  }

  if (!validEmail) email_note = 'no valid email, email draft skipped';
  else if (!e || !e.body) { email_note = 'error: bad or empty response'; failed = true; }
  else {
    subject = String(e.subject || '').trim();
    body = String(e.body).trim();
    const words = body.split(/\s+/).length;
    if (!subject) flags.push('empty subject');
    if (subject.length > 70) flags.push('subject too long');
    if (/[A-Z]/.test(subject) && subject === subject.toUpperCase()) flags.push('subject in ALL CAPS');
    if (PH.test(body) || PH.test(subject)) flags.push('placeholder left in email');
    if (SPAM.test(body) || SPAM.test(subject)) flags.push('spam words in email');
    if (!S.template) {
      if (words < 40 || words > 140) flags.push('email length ' + words + ' words');
      if ((body.match(/!/g) || []).length > 1) flags.push('exclamation marks in email');
      const src = (r.post + ' ' + r.company + ' ' + r.owner);
      const bad = (body.match(/\d[\d,.]*/g) || []).filter(n => !src.includes(n));
      if (bad.length) flags.push('number not in source: ' + bad.slice(0, 2).join(','));
    }
    body += S.template ? ('\n\n' + S.optOut) : ('\n\n' + S.signoff + '\n\n' + S.optOut);
  }
  const priority = !comment ? '' : (intent >= 4 ? 'high' : intent === 3 ? 'medium' : 'low');
  const status = failed ? 'error' : (flags.length ? 'needs_edit' : ((comment || body) ? 'draft' : 'skipped'));
  return { json: { priority, intent_score: intent || '', language, company: r.company, owner: r.owner, email: r.email,
    post: r.post.slice(0, 300), comment, comment_note, subject, body, email_note, qa_flags: flags.join('; '), status } };
});
const rank = { high: 0, medium: 1, low: 2, '': 3 };
rows.sort((a, b) => (rank[a.json.priority] - rank[b.json.priority]) || ((b.json.intent_score || 0) - (a.json.intent_score || 0)));
return rows;

const esc = (s) => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const rows = $('Build result row').all().map(i => i.json);
const tokens = [...$('Draft comment').all(), ...$('Draft email').all()].reduce((t, i) => t + ((i.json.usage && i.json.usage.total_tokens) || 0), 0);
const count = (s) => rows.filter(r => r.status === s).length;
const color = { draft: '#1a9d5c', needs_edit: '#d9a300', error: '#d33', skipped: '#888' };
const chip = (t, c) => `<span style="background:${c};color:#fff;border-radius:99px;padding:2px 9px;font-size:12px;margin-right:6px">${t}</span>`;
const cards = rows.map((r, n) => `<div style="border:1px solid #8884;border-left:5px solid ${color[r.status] || '#888'};border-radius:8px;padding:10px 12px;margin:10px 0;text-align:left">
<div><b>#${n+1} ${esc(r.company || r.owner || r.email)}</b> ${chip(esc(r.status), color[r.status] || '#888')}${r.priority ? chip('priority: ' + esc(r.priority), '#555') : ''}${r.language ? chip(esc(r.language), '#777') : ''}</div>
${r.qa_flags ? `<div style="color:#b57d00;margin-top:4px">&#9888; ${esc(r.qa_flags)}</div>` : ''}
<div style="margin-top:6px"><b>Post:</b> ${esc(r.post)}</div>
<div style="margin-top:4px"><b>Comment:</b> ${esc(r.comment) || '<i>' + esc(r.comment_note) + '</i>'}</div>
<div style="margin-top:4px"><b>Subject:</b> ${esc(r.subject) || '<i>' + esc(r.email_note) + '</i>'}</div>
${r.body ? `<div style="margin-top:4px"><b>Email:</b><div style="white-space:pre-wrap">${esc(r.body)}</div></div>` : ''}</div>`).join('');
const html = `<p>${chip(count('draft') + ' ready', color.draft)}${chip(count('needs_edit') + ' need edit', color.needs_edit)}${chip(count('error') + ' errors', color.error)}${chip(count('skipped') + ' skipped', color.skipped)} <small>&middot; ${tokens} tokens used</small></p>
<p>Drafts are saved in <code>outreach_drafts.csv</code>. To change a row: edit the CSV, set its <b>status</b> to <code>draft</code> (approve) or anything else (leave out), save and close the file, then choose below. <b>Only rows with status <code>draft</code> are exported.</b> Nothing has been posted or sent.</p>` + cards;
return [{ json: { reviewHtml: html, total: rows.length, ready: count('draft') } }];

const rows = $input.all().map(i => i.json).filter(r => String(r.status).trim().toLowerCase() === 'draft');
if (!rows.length) throw new Error('No rows with status "draft" in outreach_drafts.csv. Set status to draft for the rows you approve.');
const at = new Date().toISOString();
return rows.map(r => ({ json: { ...r, status: 'approved', reviewed_at: at } }));
